def transform(grid):
    offsets = {c-r for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0}
    period = len(offsets)
    pattern = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                pattern[(c-r) % period] = value
    return [[pattern[(c-r) % period] for c in range(len(row))] for r, row in enumerate(grid)]

